/**
 * Persona profile REFERENCE image (v7.553)
 *
 * The design reference Wayne supplied on 2026-10-10 — "The Yield-Chasing Saver"
 * profile (568×706 PNG, ≈4:5): the visual system every generated persona profile
 * must belong to. It is sent as the input image of every render (OpenAI
 * /v1/images/edits), so the prompt's "match the reference image" has a real
 * reference to match. Stored as base64 in a module (not a loose file) so the
 * route's lambda always bundles it — no output-file-tracing dependency.
 *
 * Replace the constant to change the house style; bump PERSONA_PROFILE_REFERENCE_VERSION.
 */

export const PERSONA_PROFILE_REFERENCE_VERSION = 1;
export const PERSONA_PROFILE_REFERENCE_FILENAME = 'persona-profile-reference.png';
export const PERSONA_PROFILE_REFERENCE_MIME = 'image/png';
export const PERSONA_PROFILE_REFERENCE_SIZE = { width: 568, height: 706 } as const;

export function referenceImageBytes(): Buffer {
  return Buffer.from(PERSONA_PROFILE_REFERENCE_PNG_B64, 'base64');
}

// prettier-ignore
export const PERSONA_PROFILE_REFERENCE_PNG_B64 = '';
